const rows=$input.all().map(i=>i.json).filter(r=>r.id&&r.report_code);
const now=Date.now();
const active=rows.filter(r=>r.state==='CLA_RUNNING'||r.state==='RPB_RUNNING').sort((a,b)=>Date.parse(a.processing_started_at||0)-Date.parse(b.processing_started_at||0))[0];
if(active){
  const expiry=Date.parse(active.lease_expires_at||0);
  if(!expiry||expiry>now)return[{json:{hasWork:false,state:'WAITING',active_report:active.report_code,stage:active.stage}}];
  return[{json:{...active,hasWork:true,recovery:true,correlation_id:String(active.correlation_id||active.execution_id||$execution.id),execution_id:String(active.correlation_id||active.execution_id||$execution.id),stage_attempt_count:Number(active.stage_attempt_count||0)+1,heartbeat_at:new Date().toISOString(),lease_expires_at:new Date(now+10*60000).toISOString(),last_error:'Checkpoint lease expired; retrying only '+active.stage}}];
}
const completed=new Set(rows.filter(r=>r.state==='COMPLETE').map(r=>r.report_code));
const queued=rows.filter(r=>r.state==='QUEUED'&&!completed.has(r.report_code)).sort((a,b)=>Date.parse(a.queued_at||a.createdAt||0)-Date.parse(b.queued_at||b.createdAt||0));
const row=queued[0];
if(!row)return[{json:{hasWork:false,state:'IDLE'}}];
return[{json:{...row,hasWork:true,recovery:false,state:'CLA_RUNNING',stage:'CLA_GEAR_ISSUES',processing_started_at:new Date().toISOString(),attempt_count:Number(row.attempt_count||0)+1,stage_attempt_count:1,correlation_id:String($execution.id),execution_id:String($execution.id),heartbeat_at:new Date().toISOString(),lease_expires_at:new Date(now+10*60000).toISOString(),last_error:''}}];

const r=$input.first().json;
const map={CLA_GEAR_ISSUES:['CLA','runGearIssues'],CLA_GEAR_LISTING:['CLA','runGearListing'],CLA_CONSUMABLES:['CLA','runConsumables'],CLA_DRUMS:['CLA','runDrums'],CLA_SHADOW_RESISTANCE:['CLA','runSR'],CLA_EXPORT:['CLA','runCLA'],RPB_ALL_DATA:['RPB','runAllSheet'],RPB_EXPORT_ROLES:['RPB','runExport']};
const step=map[r.stage];
const lastError=String(r.last_error||'');
const callbackMustStop=lastError.startsWith('CLA ')||lastError.startsWith('RPB ')||lastError.startsWith('Ignored ');
if(!step||callbackMustStop)return[{json:{...r,dispatch:false}}];
return[{json:{...r,dispatch:true,project:step[0],action:step[1],callbackUrl:step[0]==='CLA'?'__RCE_PUBLIC_WEBHOOK_BASE_URL__/webhook/rce/v2/callback/cla-action':'__RCE_PUBLIC_WEBHOOK_BASE_URL__/webhook/rce/v2/callback/rpb-action'}}];

const b=$('CLA Action Callback').first().json.body||$('CLA Action Callback').first().json;
const rows=$input.all().map(i=>i.json).filter(r=>r.id&&r.report_code===b.reportId);
const row=rows[0];
if(!row)throw new Error('No ledger row for CLA callback '+b.reportId);
if(b.project!=='CLA'||b.callbackStage!=='CLA_ACTION_COMPLETE'||!b.action||!b.correlationId)throw new Error('Invalid CLA action callback');
if(String(row.correlation_id||row.execution_id)!==String(b.correlationId))return[{json:{hasNext:false,ignored:true,report_code:b.reportId,last_error:'Ignored stale CLA callback',message:'Stale CLA callback ignored'}}];
const expected={CLA_GEAR_ISSUES:'runGearIssues',CLA_GEAR_LISTING:'runGearListing',CLA_CONSUMABLES:'runConsumables',CLA_DRUMS:'runDrums',CLA_SHADOW_RESISTANCE:'runSR',CLA_EXPORT:'runCLA'};
if(expected[row.stage]!==b.action)return[{json:{hasNext:false,ignored:true,report_code:b.reportId,last_error:'Ignored duplicate or out-of-order CLA callback',message:'Duplicate or out-of-order CLA callback ignored'}}];
const now=new Date();
if(b.status!=='complete'&&b.status!=='skipped')return[{json:{report_code:b.reportId,correlation_id:String(b.correlationId),execution_id:String(b.correlationId),state:'CLA_RUNNING',stage:row.stage,stage_attempt_count:Number(row.stage_attempt_count||1),heartbeat_at:now.toISOString(),lease_expires_at:now.toISOString(),callback_received_at:now.toISOString(),last_error:'CLA '+b.action+' failed: '+JSON.stringify(b.errors||b.error||b),hasNext:false}}];
const next={runGearIssues:'CLA_GEAR_LISTING',runGearListing:'CLA_CONSUMABLES',runConsumables:'CLA_DRUMS',runDrums:'CLA_SHADOW_RESISTANCE',runSR:'CLA_EXPORT',runCLA:'RPB_ALL_DATA'}[b.action];
return[{json:{report_code:b.reportId,correlation_id:String(b.correlationId),execution_id:String(b.correlationId),state:next.startsWith('RPB_')?'RPB_RUNNING':'CLA_RUNNING',stage:next,stage_attempt_count:1,heartbeat_at:now.toISOString(),lease_expires_at:new Date(now.getTime()+10*60000).toISOString(),callback_received_at:now.toISOString(),last_error:'',hasNext:true}}];

const b=$('RPB Action Callback').first().json.body||$('RPB Action Callback').first().json;
const rows=$input.all().map(i=>i.json).filter(r=>r.id&&r.report_code===b.reportId);
const row=rows[0];
if(!row)throw new Error('No ledger row for RPB callback '+b.reportId);
if(b.project!=='RPB'||b.callbackStage!=='RPB_ACTION_COMPLETE'||!b.action||!b.correlationId)throw new Error('Invalid RPB action callback');
if(String(row.correlation_id||row.execution_id)!==String(b.correlationId))return[{json:{hasNext:false,ignored:true,report_code:b.reportId,last_error:'Ignored stale RPB callback',message:'Stale RPB callback ignored'}}];
const expected={RPB_ALL_DATA:'runAllSheet',RPB_EXPORT_ROLES:'runExport'};
if(expected[row.stage]!==b.action)return[{json:{hasNext:false,ignored:true,report_code:b.reportId,last_error:'Ignored duplicate or out-of-order RPB callback',message:'Duplicate or out-of-order RPB callback ignored'}}];
const now=new Date();
if(b.status!=='complete'&&b.status!=='skipped')return[{json:{report_code:b.reportId,correlation_id:String(b.correlationId),execution_id:String(b.correlationId),state:'RPB_RUNNING',stage:row.stage,stage_attempt_count:Number(row.stage_attempt_count||1),heartbeat_at:now.toISOString(),lease_expires_at:now.toISOString(),callback_received_at:now.toISOString(),last_error:'RPB '+b.action+' failed: '+JSON.stringify(b.errors||b.error||b),hasNext:false}}];
const done=b.action==='runExport';
return[{json:{report_code:b.reportId,correlation_id:String(b.correlationId),execution_id:String(b.correlationId),state:done?'COMPLETE':'RPB_RUNNING',stage:done?'COMPLETE':'RPB_EXPORT_ROLES',stage_attempt_count:done?Number(row.stage_attempt_count||1):1,completed_at:done?now.toISOString():row.completed_at,heartbeat_at:now.toISOString(),lease_expires_at:done?null:new Date(now.getTime()+10*60000).toISOString(),callback_received_at:now.toISOString(),last_error:'',hasNext:!done}}];

const r=$input.first().json;
const keys=['report_code','state','stage','processing_started_at','attempt_count','stage_attempt_count','correlation_id','execution_id','heartbeat_at','lease_expires_at','callback_received_at','completed_at','last_error'];
const clean={};
for(const key of keys)if(r[key]!==undefined)clean[key]=r[key];
return[{json:clean}];

const response = $('Fetch Guild Reports from Warcraft Logs').first().json || {};
if ((response.statusCode || 200) >= 400) throw new Error('Warcraft Logs HTTP ' + response.statusCode);
const payload = response.body || response;
if (payload.errors?.length) throw new Error('Warcraft Logs GraphQL: ' + payload.errors.map(e => e.message).join('; '));
const reports = payload.data?.reportData?.reports?.data || [];
const ledgerRows = $input.all().map(i => i.json).filter(r => r.report_code);
const ledger = new Map(ledgerRows.map(r => [r.report_code, r]));
const nowMs = Date.now(), now = new Date(nowMs).toISOString();
const stableMs = 15 * 60 * 1000, minimumLiveMs = 60 * 60 * 1000;
const protectedStates = new Set(['QUEUED','CLA_RUNNING','RPB_RUNNING','COMPLETE']);
const output=[];
for (const report of reports) {
  if (!report.code) continue;
  const prior=ledger.get(report.code)||{}; if (prior.state==='COMPLETE') continue;
  const fights=Array.isArray(report.fights)?report.fights:[];
  const fightCount=fights.length;
  const combatDuration=fights.reduce((sum,f)=>sum+Math.max(0,Number(f.endTime||0)-Number(f.startTime||0)),0);
  const hasBossKill=fights.some(f=>f.kill===true);
  const hasFightInProgress=fights.some(f=>f.inProgress===true);
  const endMs=Number(report.endTime), startMs=Number(report.startTime);
  const changed=prior.report_end_at ? Date.parse(prior.report_end_at)!==endMs : false;
  const firstSeen=prior.first_seen_at||now;
  const reportLooksLive=nowMs-endMs<stableMs;
  const liveObserved=Boolean(prior.live_observed||changed);
  const lastChange=(changed||!prior.last_event_change_at)?now:prior.last_event_change_at;
  const reportStartMs=Number.isFinite(startMs)&&startMs>0?startMs:Date.parse(firstSeen);
  const lastChangeMs=Date.parse(lastChange);
  const minimumReached=Number.isFinite(reportStartMs)&&nowMs-reportStartMs>=minimumLiveMs;
  const stableLongEnough=!changed&&Number.isFinite(lastChangeMs)&&nowMs-lastChangeMs>=stableMs;
  const endOldEnough=Number.isFinite(endMs)&&nowMs-endMs>=stableMs;
  const enoughCombat=hasBossKill||(fightCount>=1&&combatDuration>=60000);
  const completedUploadEligible=!liveObserved&&endOldEnough&&!hasFightInProgress&&(minimumReached||hasBossKill);
  let state=prior.state||'DISCOVERED', eligibleAt=prior.eligible_at||null, queuedAt=prior.queued_at||null;
  if (!protectedStates.has(state)) {
    if (!enoughCombat) state=reportLooksLive||hasFightInProgress?'LIVE':'DISCOVERED';
    else if (completedUploadEligible) { state='QUEUED'; eligibleAt=eligibleAt||now; queuedAt=queuedAt||now; }
    else if (liveObserved && minimumReached && stableLongEnough && endOldEnough && !hasFightInProgress) { state='QUEUED'; eligibleAt=eligibleAt||now; queuedAt=queuedAt||now; }
    else state=reportLooksLive||changed||hasFightInProgress?'LIVE':'STABILIZING';
  }
  output.push({json:{report_code:report.code,expansion:prior.expansion || '__RCE_EXPANSION__',source:prior.source||'warcraftlogs-monitor',requested_by:prior.requested_by||'system',state,first_seen_at:firstSeen,last_seen_at:now,report_start_at:new Date(startMs).toISOString(),report_end_at:new Date(endMs).toISOString(),last_event_change_at:lastChange,fight_count:fightCount,combat_duration_ms:combatDuration,live_observed:liveObserved,eligible_at:eligibleAt,queued_at:queuedAt,processing_started_at:prior.processing_started_at||null,completed_at:prior.completed_at||null,attempt_count:Number(prior.attempt_count||0),last_error:prior.last_error||'',execution_id:$execution.id}});
}
return output;

const request = $('Portal Report Intake').first().json || {};
const body = request.body || {};
const reportCode = String(body.reportId || '').trim();
if (!/^[A-Za-z0-9]{16}$/.test(reportCode)) throw new Error('Invalid Warcraft Logs report ID.');
const rows = $input.all().map(i => i.json).filter(r => r.report_code === reportCode);
const priority = {COMPLETE:5,RPB_RUNNING:4,CLA_RUNNING:3,QUEUED:2};
const prior = rows.sort((a,b)=>(priority[b.state]||0)-(priority[a.state]||0))[0] || {};
const protectedStates = new Set(['QUEUED','CLA_RUNNING','RPB_RUNNING','COMPLETE']);
if (protectedStates.has(prior.state)) {
  const stateLabel = String(prior.state).toLowerCase().replaceAll('_',' ');
  const message = prior.state === 'COMPLETE' ? 'This report has already completed processing.' : 'This report is already ' + stateLabel + '.';
  return [{json:{report_code:reportCode,state:prior.state,duplicate:true,should_upsert:false,message}}];
}
const now = new Date().toISOString();
return [{json:{
  report_code: reportCode,
  expansion: prior.expansion || '__RCE_EXPANSION__',
  source: String(body.source || 'trusted-portal').slice(0,100),
  requested_by: String(body.requestedBy || 'authorized-member').slice(0,100),
  state: 'QUEUED',
  first_seen_at: prior.first_seen_at || now,
  last_seen_at: now,
  report_start_at: prior.report_start_at || null,
  report_end_at: prior.report_end_at || null,
  last_event_change_at: prior.last_event_change_at || null,
  fight_count: Number(prior.fight_count || 0),
  combat_duration_ms: Number(prior.combat_duration_ms || 0),
  live_observed: Boolean(prior.live_observed),
  eligible_at: now,
  queued_at: now,
  processing_started_at: null,
  completed_at: null,
  attempt_count: Number(prior.attempt_count || 0),
  last_error: '',
  execution_id: $execution.id,
  stage: 'QUEUED',
  correlation_id: '',
  lease_expires_at: null,
  heartbeat_at: now,
  callback_received_at: null,
  stage_attempt_count: 0,
  duplicate: false,
  should_upsert: true,
  message: 'Report accepted and queued.'
}}];

const row = $input.first().json;
const keys = ['report_code','expansion','source','requested_by','state','first_seen_at','last_seen_at','report_start_at','report_end_at','last_event_change_at','fight_count','combat_duration_ms','live_observed','eligible_at','queued_at','processing_started_at','completed_at','attempt_count','last_error','execution_id','stage','correlation_id','lease_expires_at','heartbeat_at','callback_received_at','stage_attempt_count'];
const clean = {};
for (const key of keys) if (row[key] !== undefined) clean[key] = row[key];
return [{json:clean}];
